// Lossless transport only. No scoring, filtering or evidence inference.
const prefix='~s078:';
export function encodeSimulator078(value){const counts=new Map();function count(x){if(typeof x==='string'){if(x.startsWith(prefix))throw Error('Reserved codec prefix');counts.set(x,(counts.get(x)||0)+1);}else if(Array.isArray(x))x.forEach(count);else if(x&&typeof x==='object')Object.values(x).forEach(count);}count(value);const strings=[...counts].filter(([s,n])=>n>=3&&s.length>=24||n>=8&&s.length>=12).map(([s])=>s),map=new Map(strings.map((s,i)=>[s,i]));function pack(x){if(typeof x==='string'&&map.has(x))return prefix+map.get(x);if(Array.isArray(x))return x.map(pack);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,pack(v)]));return x;}return{transport:'string-pool-078',strings,data:pack(value)};}
export function decodeSimulator078(value){if(value.transport!=='string-pool-078')return value;const strings=value.strings;function unpack(x){if(typeof x==='string'&&x.startsWith(prefix)){const n=Number(x.slice(prefix.length));if(!Number.isInteger(n)||n<0||n>=strings.length)throw Error('Invalid string pool reference');return strings[n];}if(Array.isArray(x))return x.map(unpack);if(x&&typeof x==='object')return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,unpack(v)]));return x;}return unpack(value.data);}
const escape=k=>k.replaceAll('~','~0').replaceAll('/','~1'),unescape=k=>k.replaceAll('~1','/').replaceAll('~0','~');
export function deltaSimulator078(a,b,path=''){if(JSON.stringify(a)===JSON.stringify(b))return[];if(!a||!b||typeof a!=='object'||typeof b!=='object'||Array.isArray(a)!==Array.isArray(b)||Array.isArray(a)&&a.length!==b.length)return[{op:'replace',path,value:b}];if(Array.isArray(a))return a.flatMap((x,i)=>deltaSimulator078(x,b[i],path+'/'+i));const ops=Object.keys(a).filter(k=>!Object.hasOwn(b,k)).map(k=>({op:'remove',path:path+'/'+escape(k)}));for(const[k,v]of Object.entries(b)){const p=path+'/'+escape(k);if(!Object.hasOwn(a,k))ops.push({op:'add',path:p,value:v});else ops.push(...deltaSimulator078(a[k],v,p));}return ops;}
export function applySimulatorDelta078(base,operations){let out=structuredClone(base);for(const x of operations){if(!x.path){if(x.op!=='replace')throw Error('Invalid root delta');out=structuredClone(x.value);continue;}const keys=x.path.slice(1).split('/').map(unescape),key=keys.pop();if(keys.some(k=>['__proto__','prototype','constructor'].includes(k))||['__proto__','prototype','constructor'].includes(key))throw Error('Unsafe delta path');let target=out;for(const k of keys){if(!target||!Object.hasOwn(target,k))throw Error('Missing delta path');target=target[k];}if(x.op==='remove')delete target[key];else if(['replace','add'].includes(x.op))target[key]=structuredClone(x.value);else throw Error('Unsupported delta operation');}return out;}
